sap.ui.define(
  [
    "sap/ui/core/UIComponent",
    "sap/ui/model/json/JSONModel",
    "odata/metadata/manager/model/mockData",
  ],
  function (UIComponent, JSONModel, MockData) {
    "use strict";

    return UIComponent.extend("odata.metadata.manager.Component", {
      metadata: {
        manifest: "json",
      },

      init: function () {
        // Call super init first
        UIComponent.prototype.init.apply(this, arguments);

        // Set up the main JSON model with mock data
        var oModel = new JSONModel(MockData.getData());
        this.setModel(oModel);

        // Initialize the router
        this.getRouter().initialize();
      },

      destroy: function () {
        UIComponent.prototype.destroy.apply(this, arguments);
      },
    });
  },
);

sap.ui.define(
  [
    "sap/ui/core/UIComponent",
    "sap/ui/model/json/JSONModel",
    "odata/metadata/manager/model/DataService",
    "odata/metadata/manager/model/Config",
  ],
  function (UIComponent, JSONModel, DataService, Config) {
    "use strict";

    return UIComponent.extend("odata.metadata.manager.Component", {
      metadata: {
        manifest: "json",
      },

      init: function () {
        // Call super init first
        UIComponent.prototype.init.apply(this, arguments);

        // Log configuration (if debug mode enabled)
        Config.logConfiguration();

        // Create data service (factory pattern)
        var oDataService = DataService.createDataService(this);
        this._oDataService = oDataService;

        // Initialize model with data
        this._initializeModel(oDataService, oDataService.getStatus ? oDataService.getStatus() : null);

        // Initialize the router
        this.getRouter().initialize();
      },

      /**
       * Initialize the main JSON model
       * @param {Object} oDataService - Data service instance
       * @param {Object} oStatus - Service status
       * @private
       */
      _initializeModel: function (oDataService, oStatus) {
        var oModel = new JSONModel();
        this.setModel(oModel);

        // Load data from service
        oDataService.read(
          function (oData) {
            // Update model with data from service
            if (oData) {
              oModel.setData(oData);
            }
            console.log(
              "[Component] Data service initialized:",
              oStatus ? oStatus.backend : "Mock Data"
            );
          },
          function (oError) {
            console.error("[Component] Failed to load data:", oError);
            // Fallback: empty model
            oModel.setData({});
          }
        );
      },

      /**
       * Get data service instance
       * @returns {Object} Data service reference
       */
      getDataService: function () {
        return this._oDataService;
      },

      destroy: function () {
        UIComponent.prototype.destroy.apply(this, arguments);
      },
    });
  },
);

{
  "_version": "1.59.0",
  "sap.app": {
    "id": "odata.metadata.manager",
    "type": "application",
    "title": "OData Metadata Manager",
    "description": "Manage, compare and snapshot OData service metadata versions",
    "applicationVersion": { "version": "1.0.0" },
    "dataSources": {}
  },
  "sap.ui": {
    "technology": "UI5",
    "icons": {
      "icon": "sap-icon://database",
      "favIcon": "",
      "phone": "",
      "phone@2": "",
      "tablet": "",
      "tablet@2": ""
    },
    "deviceTypes": {
      "desktop": true,
      "tablet": true,
      "phone": false
    },
    "supportedThemes": ["sap_horizon", "sap_fiori_3"]
  },
  "sap.ui5": {
    "rootView": {
      "viewName": "odata.metadata.manager.view.App",
      "type": "XML",
      "id": "app"
    },
    "dependencies": {
      "minUI5Version": "1.120.0",
      "libs": {
        "sap.m": {},
        "sap.ui.layout": {},
        "sap.f": {},
        "sap.ui.unified": {}
      }
    },
    "contentDensities": {
      "compact": true,
      "cozy": true
    },
    "models": {
      "": {
        "type": "sap.ui.model.json.JSONModel",
        "settings": { "defaultBindingMode": "TwoWay" }
      }
    },
    "routing": {
      "config": {
        "routerClass": "sap.m.routing.Router",
        "viewType": "XML",
        "path": "odata.metadata.manager.view",
        "controlId": "navContainer",
        "controlAggregation": "pages",
        "async": true
      },
      "routes": [
        { "name": "dashboard", "pattern": "", "target": ["dashboard"] },
        {
          "name": "versionCompare",
          "pattern": "compare/{service}",
          "target": ["versionCompare"]
        },
        {
          "name": "snapshotDetail",
          "pattern": "snapshot/{service}/{version}",
          "target": ["snapshotDetail"]
        }
      ],
      "targets": {
        "dashboard": {
          "viewType": "XML",
          "viewName": "Dashboard",
          "viewId": "dashboard"
        },
        "versionCompare": {
          "viewType": "XML",
          "viewName": "VersionCompare",
          "viewId": "versionCompare"
        },
        "snapshotDetail": {
          "viewType": "XML",
          "viewName": "SnapshotDetail",
          "viewId": "snapshotDetail"
        }
      }
    }
  }
}

