sap.ui.define([], function () {
  "use strict";

  return {
    // ─── Backend Configuration ──────────────────────────────────────────
    // Set to true when RAP backend is ready and configured
    BACKEND_ENABLED: false,

    // Backend service URL (activate when BACKEND_ENABLED is true)
    // Format: https://<host>:<port>/sap/opu/odata/sap/<RAP_SERVICE>
    // Example: "https://sap-system.example.com:8443/sap/opu/odata/sap/ZMM_METADATA_SRV"
    BACKEND_URL: "",

    // OData Version: "v2" or "v4"
    // Most RAP services default to v4
    ODATA_VERSION: "v4",

    // Entity set mappings for OData binding
    // Update these when connecting to actual RAP backend
    ENTITY_SETS: {
      services: "Services",           // Mock: "services", RAP: "Services"
      snapshots: "Snapshots",         // Mock: "snapshots", RAP: "Snapshots"
      compareData: "CompareData",     // Mock: "compareData", RAP: "CompareData"
      snapshotDetail: "SnapshotDetails", // Mock: "snapshotDetail", RAP: "SnapshotDetails"
    },

    // Authentication type: "None", "Basic", "OAuth", "SAML"
    AUTH_TYPE: "None",

    // Request timeout in milliseconds
    REQUEST_TIMEOUT: 30000,

    // Enable request/response logging
    DEBUG_MODE: false,

    // ─── Helper Methods ────────────────────────────────────────────────

    /**
     * Check if backend is enabled
     * @returns {boolean}
     */
    isBackendEnabled: function () {
      return this.BACKEND_ENABLED && this.BACKEND_URL !== "";
    },

    /**
     * Get entity set name for given resource
     * @param {string} sResource - Resource key (e.g., "services", "snapshots")
     * @returns {string} Entity set name
     */
    getEntitySet: function (sResource) {
      return this.ENTITY_SETS[sResource] || sResource;
    },

    /**
     * Get OData model settings for component initialization
     * @returns {Object} Model settings object
     */
    getODataModelSettings: function () {
      return {
        type: "sap.ui.model.odata." + this.ODATA_VERSION + ".ODataModel",
        uri: this.BACKEND_URL,
        settings: {
          defaultBindingMode: "TwoWay",
          metadataUrlParams: { sap_theme: "sap_horizon" },
          json: true,
          timeout: this.REQUEST_TIMEOUT,
        },
      };
    },

    /**
     * Get JSON model settings (for mock data)
     * @returns {Object} Model settings object
     */
    getJSONModelSettings: function () {
      return {
        type: "sap.ui.model.json.JSONModel",
        settings: {
          defaultBindingMode: "TwoWay",
        },
      };
    },

    /**
     * Log configuration for debugging
     */
    logConfiguration: function () {
      if (this.DEBUG_MODE) {
        console.log("=== Data Service Configuration ===");
        console.log("Backend Enabled:", this.isBackendEnabled());
        console.log("Backend URL:", this.BACKEND_URL);
        console.log("OData Version:", this.ODATA_VERSION);
        console.log("Auth Type:", this.AUTH_TYPE);
        console.log("Entity Sets:", this.ENTITY_SETS);
      }
    },
  };
});

sap.ui.define(
  [
    "odata/metadata/manager/model/MockDataService",
    "odata/metadata/manager/model/ODataService",
    "odata/metadata/manager/model/Config",
  ],
  function (MockDataService, ODataService, Config) {
    "use strict";

    return {
      /**
       * Factory function to create appropriate data service based on configuration
       * @param {sap.ui.core.UIComponent} oComponent - Reference to component for model access
       * @returns {Object} DataService instance (MockDataService or ODataService)
       */
      createDataService: function (oComponent) {
        var bUseBackend = Config.isBackendEnabled();

        if (bUseBackend) {
          return ODataService.createInstance(oComponent);
        } else {
          return MockDataService.createInstance();
        }
      },

      /**
       * Get configuration helper
       * @returns {Object} Config module reference
       */
      getConfig: function () {
        return Config;
      },
    };
  }
);

sap.ui.define(
  ["odata/metadata/manager/model/mockData"],
  function (MockData) {
    "use strict";

    return {
      /**
       * Create a MockDataService instance
       * @returns {Object} Service object with read/create/update/delete methods
       */
      createInstance: function () {
        return {
          /**
           * Read initial data
           * @param {Function} fnSuccess - Success callback
           * @param {Function} fnError - Error callback
           */
          read: function (fnSuccess, fnError) {
            try {
              var oData = MockData.getData();
              if (fnSuccess) {
                fnSuccess(oData);
              }
            } catch (ex) {
              if (fnError) {
                fnError(ex);
              }
            }
          },

          /**
           * Create a new entity (mock: just log)
           * @param {string} sEntitySet - Entity set name
           * @param {Object} oData - Entity data
           * @param {Function} fnSuccess - Success callback
           * @param {Function} fnError - Error callback
           */
          create: function (sEntitySet, oData, fnSuccess, fnError) {
            console.log("[MockDataService] Creating entity in:", sEntitySet, oData);
            if (fnSuccess) {
              fnSuccess({ id: "mock_" + Date.now(), ...oData });
            }
          },

          /**
           * Update an entity (mock: just log)
           * @param {string} sEntitySet - Entity set name
           * @param {string} sKey - Entity key
           * @param {Object} oData - Updated data
           * @param {Function} fnSuccess - Success callback
           * @param {Function} fnError - Error callback
           */
          update: function (sEntitySet, sKey, oData, fnSuccess, fnError) {
            console.log("[MockDataService] Updating entity in:", sEntitySet, sKey, oData);
            if (fnSuccess) {
              fnSuccess(oData);
            }
          },

          /**
           * Delete an entity (mock: just log)
           * @param {string} sEntitySet - Entity set name
           * @param {string} sKey - Entity key
           * @param {Function} fnSuccess - Success callback
           * @param {Function} fnError - Error callback
           */
          delete: function (sEntitySet, sKey, fnSuccess, fnError) {
            console.log("[MockDataService] Deleting entity from:", sEntitySet, sKey);
            if (fnSuccess) {
              fnSuccess();
            }
          },

          /**
           * Query entities with filters
           * @param {string} sEntitySet - Entity set name
           * @param {Object} oFilters - Filter criteria
           * @param {Function} fnSuccess - Success callback
           * @param {Function} fnError - Error callback
           */
          query: function (sEntitySet, oFilters, fnSuccess, fnError) {
            console.log("[MockDataService] Querying:", sEntitySet, oFilters);
            var oData = MockData.getData();
            var aResults = oData[sEntitySet] || [];
            if (fnSuccess) {
              fnSuccess(aResults);
            }
          },

          /**
           * Check service status
           * @returns {Object} Status object
           */
          getStatus: function () {
            return {
              isOnline: true,
              isMock: true,
              backend: "Mock Data Service",
            };
          },
        };
      },
    };
  }
);

sap.ui.define(
  ["sap/ui/model/odata/v2/ODataModel", "sap/ui/model/odata/v4/ODataModel", "odata/metadata/manager/model/Config"],
  function (ODataModelV2, ODataModelV4, Config) {
    "use strict";

    return {
      /**
       * Create an ODataService instance
       * @param {sap.ui.core.UIComponent} oComponent - Component reference
       * @returns {Object} Service object with read/create/update/delete methods
       */
      createInstance: function (oComponent) {
        var sODataVersion = Config.ODATA_VERSION;
        var sBackendUrl = Config.BACKEND_URL;

        // Determine OData model class
        var ODataModelClass = sODataVersion === "v4" ? ODataModelV4 : ODataModelV2;

        // Model initialization settings
        var oModelSettings = {
          defaultBindingMode: "TwoWay",
          metadataUrlParams: { sap_theme: "sap_horizon" },
          json: true,
          timeout: Config.REQUEST_TIMEOUT,
        };

        // Create OData model (to be attached to component)
        var oModel = new ODataModelClass(sBackendUrl, oModelSettings);

        return {
          /**
           * Read initial data via OData
           * @param {Function} fnSuccess - Success callback
           * @param {Function} fnError - Error callback
           */
          read: function (fnSuccess, fnError) {
            // For OData, data is fetched via model binding
            // This callback ensures data is ready
            oModel.attachMetadataLoaded(function () {
              if (fnSuccess) {
                fnSuccess();
              }
            });

            oModel.attachMetadataFailed(function (oEvent) {
              if (fnError) {
                fnError(oEvent);
              }
            });
          },

          /**
           * Create a new entity via OData
           * @param {string} sEntitySet - Entity set name
           * @param {Object} oData - Entity data
           * @param {Function} fnSuccess - Success callback
           * @param {Function} fnError - Error callback
           */
          create: function (sEntitySet, oData, fnSuccess, fnError) {
            var sPath = "/" + Config.getEntitySet(sEntitySet);

            oModel.create(sPath, oData, {
              success: fnSuccess,
              error: fnError,
              async: true,
            });
          },

          /**
           * Update an entity via OData
           * @param {string} sEntitySet - Entity set name
           * @param {string} sKey - Entity key
           * @param {Object} oData - Updated data
           * @param {Function} fnSuccess - Success callback
           * @param {Function} fnError - Error callback
           */
          update: function (sEntitySet, sKey, oData, fnSuccess, fnError) {
            var sPath = "/" + Config.getEntitySet(sEntitySet) + "(" + sKey + ")";

            oModel.update(sPath, oData, {
              success: fnSuccess,
              error: fnError,
              async: true,
            });
          },

          /**
           * Delete an entity via OData
           * @param {string} sEntitySet - Entity set name
           * @param {string} sKey - Entity key
           * @param {Function} fnSuccess - Success callback
           * @param {Function} fnError - Error callback
           */
          delete: function (sEntitySet, sKey, fnSuccess, fnError) {
            var sPath = "/" + Config.getEntitySet(sEntitySet) + "(" + sKey + ")";

            oModel.remove(sPath, {
              success: fnSuccess,
              error: fnError,
              async: true,
            });
          },

          /**
           * Query entities with filters via OData
           * @param {string} sEntitySet - Entity set name
           * @param {Object} oFilters - Filter criteria
           * @param {Function} fnSuccess - Success callback
           * @param {Function} fnError - Error callback
           */
          query: function (sEntitySet, oFilters, fnSuccess, fnError) {
            var sPath = "/" + Config.getEntitySet(sEntitySet);
            var oRequest = {
              urlParameters: oFilters,
              async: true,
            };

            oModel.read(sPath, {
              ...oRequest,
              success: function (oData) {
                if (fnSuccess) {
                  fnSuccess(oData.results || oData);
                }
              },
              error: fnError,
            });
          },

          /**
           * Get the underlying OData model
           * @returns {Object} ODataModel instance
           */
          getModel: function () {
            return oModel;
          },

          /**
           * Check service status
           * @returns {Object} Status object
           */
          getStatus: function () {
            return {
              isOnline: true,
              isMock: false,
              backend: sBackendUrl,
              odataVersion: sODataVersion,
            };
          },
        };
      },
    };
  }
);
